<template><div><div class="page-head"><div><h1>Dashboard</h1><p class="muted">Overview of VORA commerce operations.</p></div><button class="btn secondary">Last 30 days <ChevronDown :size="15"/></button></div><div class="metrics"><div v-for="m in metrics" :key="m.label" class="metric card"><span>{{m.label}}</span><b>{{m.value}}</b><small :class="{positive:m.change>0}">{{m.change>0?'+':''}}{{m.change}}% vs last period</small></div></div><div class="dash-grid"><section class="card panel"><div class="panel-head"><b>Revenue</b><span class="muted">Monthly</span></div><div class="chart"><div v-for="(v,i) in bars" :key="i" :style="{height:v+'%'}"></div></div><div class="axis"><span>Jan</span><span>Feb</span><span>Mar</span><span>Apr</span><span>May</span><span>Jun</span></div></section><section class="card panel"><div class="panel-head"><b>Order status</b></div><div class="status-list"><div v-for="s in statuses" :key="s.label"><span>{{s.label}}</span><b>{{s.value}}</b><i><em :style="{width:s.percent+'%'}"></em></i></div></div></section></div><section class="card table-card"><div class="panel-head"><b>Recent orders</b><RouterLink to="/orders">View all</RouterLink></div><div class="table-wrap"><table class="table"><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th><th>Date</th></tr></thead><tbody><tr v-for="o in orders.slice(0,4)" :key="o.id"><td><RouterLink :to="`/orders/${o.id}`"><b>{{o.id}}</b></RouterLink></td><td>{{o.customer}}</td><td>{{format(o.total)}} EGP</td><td><span class="badge">{{o.status}}</span></td><td>{{o.date}}</td></tr></tbody></table></div></section></div></template>
